ansible/roles/nemoclaw/tasks/main.json:
[
  {
    "ansible.builtin.package": {
      "name": [
        "curl",
        "git",
        "binutils",
        "zstd",
        "docker.io"
      ],
      "state": "present"
    },
    "name": "Install NemoClaw prerequisites"
  },
  {
    "ansible.builtin.systemd": {
      "enabled": true,
      "name": "docker",
      "state": "started"
    },
    "name": "Start NemoClaw engine"
  },
  {
    "ansible.builtin.shell": {
      "cmd": "test -f /opt/bromigos-nemoclaw/installed || { test ! -e /root/.nemoclaw && test ! -e /root/.openshell && test ! -e /root/.local/bin/nemoclaw && ! command -v nemoclaw >/dev/null 2>&1; }"
    },
    "changed_when": false,
    "name": "Check for an unrelated NemoClaw installation"
  },
  {
    "ansible.builtin.shell": {
      "cmd": "test ! -f /opt/bromigos-nemoclaw/installed || grep -qx 24dea473621ab3517861a0386ea65ed40fd70b195971df02aeb76c4aacd83ae1 /opt/bromigos-nemoclaw/installed"
    },
    "changed_when": false,
    "name": "Refuse a changed existing sandbox plan"
  },
  {
    "ansible.builtin.git": {
      "dest": "/opt/bromigos-nemoclaw/source",
      "repo": "https://github.com/NVIDIA/NemoClaw",
      "update": false,
      "version": "2bbb4d1e3a25a49e3a9508c5e49de772afb8cded"
    },
    "name": "Fetch reviewed NemoClaw source"
  },
  {
    "ansible.builtin.shell": {
      "cmd": "set -eu; set -a; . /opt/bromigos-agents/nemoclaw.env; set +a; bash /opt/bromigos-nemoclaw/source/install.sh; echo 24dea473621ab3517861a0386ea65ed40fd70b195971df02aeb76c4aacd83ae1 > /opt/bromigos-nemoclaw/installed",
      "creates": "/opt/bromigos-nemoclaw/installed"
    },
    "environment": {
      "NEMOCLAW_ACCEPT_THIRD_PARTY_SOFTWARE": "1",
      "NEMOCLAW_ENDPOINT_URL": "https://models.example.org/v1",
      "NEMOCLAW_INSTALL_REF": "2bbb4d1e3a25a49e3a9508c5e49de772afb8cded",
      "NEMOCLAW_MODEL": "example-model",
      "NEMOCLAW_NON_INTERACTIVE": "1",
      "NEMOCLAW_POLICY_TIER": "restricted",
      "NEMOCLAW_PROVIDER": "custom",
      "NEMOCLAW_SANDBOX_NAME": "lab-assistant",
      "NEMOCLAW_TRUSTED_PRIVATE_HOSTS": "models.example.org",
      "NEMOCLAW_WEB_SEARCH_PROVIDER": "none"
    },
    "name": "Install and onboard a new restricted sandbox"
  },
  {
    "ansible.builtin.command": {
      "argv": [
        "/root/.local/bin/nemoclaw",
        "lab-assistant",
        "exec",
        "--",
        "openclaw",
        "config",
        "set",
        "tools",
        "{\"allow\": [\"session_status\", \"memory_get\"], \"deny\": [\"group:runtime\", \"group:fs\", \"group:ui\", \"group:nodes\", \"group:automation\", \"sessions_spawn\", \"subagents\"]}"
      ]
    },
    "changed_when": false,
    "name": "Disable sandbox shell and file tools"
  },
  {
    "ansible.builtin.command": {
      "argv": [
        "/root/.local/bin/nemoclaw",
        "lab-assistant",
        "gateway",
        "restart"
      ]
    },
    "changed_when": false,
    "name": "Restart the configured sandbox gateway"
  },
  {
    "ansible.builtin.command": {
      "argv": [
        "/root/.local/bin/nemoclaw",
        "lab-assistant",
        "status"
      ]
    },
    "changed_when": false,
    "name": "Verify managed sandbox"
  }
]
